# Variant of 0934a4d8
# Dimension: D1 — 对称类型 (match_cond)
# Change: 双轴对称（LR + UD），反射轴位于 [lo..N-1] 区间的中心... → 平移对称（周期性铺贴）

from __future__ import annotations

import numpy as np

from arc_utils import bbox


# Design analysis for the D1 variant
# ----------------------------------
# spec:
#   grid:
#     - 30x30 square canvas, same size as the original seed.
#     - The clean grid is generated by exact periodic tiling of one primitive tile.
#   colors:
#     - Same 8 non-marker colors {1,2,3,4,5,6,7,9}; marker color remains 8.
#   periodic structure:
#     - Row and column periods are chosen independently from {3,5,6,10}.
#     - Each chosen period divides 30, so the whole canvas is a full tiling with
#       at least 3 repeats per axis; this makes the repetition visible to humans
#       and guarantees multiple copies of each hidden cell.
#     - The tile is rejected unless the occluded grid still reveals the chosen
#       periods as the smallest valid visible periods.
#   marker:
#     - Same object type as the original task: one solid filled rectangle of color 8.
#     - Height/width remain 3..9, area remains 16..36, placement can be anywhere.
#   recovery:
#     - The output is still the marker-sized rectangle hidden under the marker.
#     - Each hidden cell is recovered from the unique visible value in its
#       translation class: all cells with the same (row mod period, col mod period).
#
# concrete behavior trace:
#   - Original seed: a hidden cell at (r,c) was matched to its LR/UD reflection
#     orbit, and some border cases used g[c,r] as a transpose fallback.
#   - Variant: a hidden cell at (r,c) is matched to positions
#       (r + k*row_period, c + t*col_period)
#     that remain on the board. Example: if periods are (5,6), then (12,17),
#     (17,17), (22,17), (27,17), (12,23), ... all encode the same tile cell.
#   - The solver therefore changes at the orbit-detection stage: reflections and
#     transpose fallback disappear, replaced by period discovery plus residue-class
#     lookup.
#
# complexity calibration:
#   - The period choices stay in a small discrete family, so the rule is not
#     underdetermined.
#   - Random primitive tiles make the periodicity visually obvious and prevent the
#     new task from collapsing back to a mirror rule.
#   - Periods are not exposed by color ids or metadata; they must be read from
#     the repeated geometry of the visible pattern.
#
# implicit-assumption audit:
#   - The original _find_reflected_strip_start assumed one bilateral mirror strip.
#     That assumption is false here, so the helper is removed entirely.
#   - The original _reflection_orbit_values assumed hidden cells share values with
#     reflected copies or a transpose. That is also false here.
#   - The new main() assumes:
#       1. there is exactly one solid rectangular marker color;
#       2. the smallest visible row/column periods are the true tiling periods;
#       3. every hidden residue class has at least one visible copy.
#     The generator enforces all three by construction and by self-checking
#     period detection on the occluded grid before accepting a sample.
#
# placement legality / visual cleanliness:
#   - There is still only one special overlay object, so the figure remains clean.
#   - The marker never leaves the board and never needs overlap handling.
#   - Placements that hide an entire translation class are rejected, so solver
#     lookups never face an empty class.
#
# observability / non-degeneration:
#   - The entire canvas participates in the periodic rule; there is no free border.
#   - Because the visible board is a repeated tile rather than a mirrored block,
#     the new behavior is visually distinct in 2-4 examples.


def _solid_rectangle_marker(g: np.ndarray) -> tuple[int, tuple[int, int, int, int]]:
    candidates: list[tuple[int, int, tuple[int, int, int, int]]] = []
    for color in np.unique(g):
        mask = g == int(color)
        b = bbox(mask)
        assert b is not None
        r0, c0, r1, c1 = b
        area = int((r1 - r0 + 1) * (c1 - c0 + 1))
        if area > 1 and int(mask.sum()) == area and bool(np.all(mask[r0 : r1 + 1, c0 : c1 + 1])):
            candidates.append((area, int(color), b))

    assert len(candidates) == 1
    _area, color, b = candidates[0]
    return color, b


def _candidate_periods(n: int) -> list[int]:
    return [p for p in range(1, n) if n % p == 0]


def _axis_period_matches(g: np.ndarray, period: int, marker: int, axis: int) -> bool:
    if axis == 0:
        a = g[:-period, :]
        b = g[period:, :]
    else:
        a = g[:, :-period]
        b = g[:, period:]

    known = (a != marker) & (b != marker)
    return not bool(np.any((a != b) & known))


def _find_period(g: np.ndarray, marker: int, axis: int) -> int:
    n = int(g.shape[axis])
    for period in _candidate_periods(n):
        if _axis_period_matches(g, period, marker, axis):
            return period
    raise AssertionError("no visible period found")


def _periodic_class_values(g: np.ndarray, r: int, c: int, row_period: int, col_period: int, marker: int) -> set[int]:
    values: set[int] = set()
    row_start = int(r % row_period)
    col_start = int(c % col_period)
    for rr in range(row_start, int(g.shape[0]), row_period):
        for cc in range(col_start, int(g.shape[1]), col_period):
            value = int(g[rr, cc])
            if value != marker:
                values.add(value)
    return values


def main(grid: np.ndarray) -> np.ndarray:
    """
    Recover the rectangle hidden by the solid marker using the grid's translation periods.

    Input structure:
    - A square colored pattern contains one solid rectangular marker color covering a patch.
    - The clean pattern is not mirror-symmetric; instead, the entire board is produced by
      periodically tiling a smaller row-period x col-period motif.
    - Visible cells outside the marker therefore repeat at fixed row and column intervals.

    Rule:
    - Find the unique color whose whole extent forms a solid rectangle; that rectangle is the output window.
    - Infer the smallest visible row period and column period that make all non-marker cells consistent under translation.
    - For each marker cell, collect the non-marker cells at the same position inside other tile copies
      (same row modulo row period and same column modulo column period) and copy their unique value.

    Key insight:
    The marker hides one crop of a periodically repeated tile, so the missing content is recovered by matching
    modulo-period residue classes rather than by reflecting across symmetry axes.
    """
    g = np.asarray(grid, dtype=int)
    marker, (r0, c0, r1, c1) = _solid_rectangle_marker(g)
    row_period = _find_period(g, marker, axis=0)
    col_period = _find_period(g, marker, axis=1)

    h = int(r1 - r0 + 1)
    w = int(c1 - c0 + 1)
    out = np.empty((h, w), dtype=int)

    for rr in range(h):
        for cc in range(w):
            r = int(r0 + rr)
            c = int(c0 + cc)
            values = _periodic_class_values(g, r, c, row_period, col_period, marker)
            assert len(values) == 1
            out[rr, cc] = values.pop()

    return out


# --------------- generator (o5x) ---------------

# --- CFG: canvas & structure ---
_N = 30
_PERIOD_CHOICES = (3, 5, 6, 10)

# --- CFG: colors ---
_PALETTE = np.array([1, 2, 3, 4, 5, 6, 7, 9], dtype=int)
_MARKER = 8

# --- CFG: marker rectangle size ---
_MARKER_DIM_LO = 3
_MARKER_DIM_HI = 9
_MARKER_AREA_LO = 16
_MARKER_AREA_HI = 36

# --- CFG: generation retries ---
_MAX_RETRIES = 400

_RNG = np.random.default_rng()
_SIZE_PAIRS = [
    (h, w)
    for h in range(_MARKER_DIM_LO, _MARKER_DIM_HI + 1)
    for w in range(_MARKER_DIM_LO, _MARKER_DIM_HI + 1)
    if _MARKER_AREA_LO <= h * w <= _MARKER_AREA_HI
]
_PERIOD_PAIRS = [(rp, cp) for rp in _PERIOD_CHOICES for cp in _PERIOD_CHOICES]
_PLACEMENT_CACHE: dict[tuple[int, int, int, int], list[tuple[int, int]]] = {}


def _build_clean(row_period: int, col_period: int) -> np.ndarray:
    tile = _RNG.choice(_PALETTE, size=(row_period, col_period))
    return np.tile(tile, (_N // row_period, _N // col_period))


def _placement_has_visible_copy(r0: int, c0: int, h: int, w: int, row_period: int, col_period: int) -> bool:
    r1 = r0 + h
    c1 = c0 + w
    for r in range(r0, r1):
        for c in range(c0, c1):
            found_visible = False
            for rr in range(r % row_period, _N, row_period):
                for cc in range(c % col_period, _N, col_period):
                    if not (r0 <= rr < r1 and c0 <= cc < c1):
                        found_visible = True
                        break
                if found_visible:
                    break
            if not found_visible:
                return False
    return True


def _valid_placements(h: int, w: int, row_period: int, col_period: int) -> list[tuple[int, int]]:
    key = (h, w, row_period, col_period)
    if key not in _PLACEMENT_CACHE:
        placements: list[tuple[int, int]] = []
        for r0 in range(_N - h + 1):
            for c0 in range(_N - w + 1):
                if _placement_has_visible_copy(r0, c0, h, w, row_period, col_period):
                    placements.append((r0, c0))
        _PLACEMENT_CACHE[key] = placements
    return _PLACEMENT_CACHE[key]


def _gen_attempt() -> np.ndarray | None:
    row_period, col_period = _PERIOD_PAIRS[int(_RNG.integers(len(_PERIOD_PAIRS)))]
    clean = _build_clean(row_period, col_period)

    h, w = _SIZE_PAIRS[int(_RNG.integers(len(_SIZE_PAIRS)))]
    placements = _valid_placements(h, w, row_period, col_period)
    if not placements:
        return None
    r0, c0 = placements[int(_RNG.integers(len(placements)))]

    expected = clean[r0 : r0 + h, c0 : c0 + w].copy()
    inp = clean.copy()
    inp[r0 : r0 + h, c0 : c0 + w] = _MARKER

    try:
        if _find_period(inp, _MARKER, axis=0) != row_period:
            return None
        if _find_period(inp, _MARKER, axis=1) != col_period:
            return None
        if np.array_equal(main(inp), expected):
            return inp
    except Exception:
        return None
    return None


def generate_input() -> np.ndarray:
    for _ in range(_MAX_RETRIES):
        grid = _gen_attempt()
        if grid is not None:
            return grid
    raise RuntimeError("failed to generate a valid 0934a4d8 input")
